static pthread_key_t ctx_key;
static pthread_once_t key_once = PTHREAD_ONCE_INIT;

static void make_key(void) { pthread_key_create(&ctx_key, ctx_free); }

struct ctx *ctx(void) {
    pthread_once(&key_once, make_key);        /* key created once per process */
    struct ctx *c = pthread_getspecific(ctx_key);
    if (!c) { c = ctx_new(); pthread_setspecific(ctx_key, c); }
    return c;                                 /* no lock on the hot path */
}

